namespace Inventory;

/// <summary>Allocates available stock across a warehouse's zones.</summary>
public sealed class AllocationCalculator
{
    public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
    {
        var result = new List<string>();
        int remaining = item.OnHand - item.Reserved;
        if (remaining <= 0)
            return result;

        foreach (var zone in warehouse.Zones)
        {
            if (TryAllocate(zone.Name, zone.Capacity, ref remaining, result))
                break;
        }

        if (remaining > 0)
            result.Add($"OVERFLOW:{remaining}");

        return result;
    }

    private static bool TryAllocate(
        string? zoneName,
        int capacity,
        ref int remaining,
        ICollection<string> result)
    {
        if (capacity <= 0 || string.IsNullOrEmpty(zoneName))
            return false;

        int place = CalculatePlacement(remaining, capacity);
        if (place <= 0)
            return false;

        result.Add($"{zoneName}:{place}");
        remaining -= place;
        return remaining <= 0;
    }

    private static int CalculatePlacement(int remaining, int capacity)
    {
        if (remaining > capacity)
            return capacity;

        if (remaining > capacity / 2)
            return remaining - 1;

        return remaining;
    }
}
